select g.date, count(*) team_rows, count(t."powerPlayToi") with_pp_toi, count(*) filter (where t."powerPlayToi" is null) null_pp_toi, (select count(distinct game_id) from nhl_api_shift_rows s where s.game_id in (select id from games where date=g.date)) games_with_raw_shifts from games g join "teamGameStats" t on t."gameId"=g.id where g.date between '2026-11-13' and '2026-11-15' group by 1 order by 1
